create extension if not exists pgcrypto;
create type public.user_role as enum ('owner','president','moderator','user');
create type public.user_status as enum ('pending','approved','rejected','suspended','disabled');
create type public.tournament_status as enum ('draft','registration_open','registration_closed','in_progress','completed','cancelled');
create type public.match_status as enum ('scheduled','live','completed','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',username text unique not null,email text,phone text,efootball_id text,avatar_url text,role public.user_role not null default 'user',status public.user_status not null default 'pending',joined_at timestamptz default now(),updated_at timestamptz default now());
create table public.tournaments(id uuid primary key default gen_random_uuid(),name text not null,description text,format text default 'Knockout',capacity int not null check(capacity in(16,32)),banner_url text,registration_start timestamptz,registration_end timestamptz,tournament_date timestamptz,rules text,status public.tournament_status default 'draft',winner_id uuid references public.profiles(id),runner_up_id uuid references public.profiles(id),created_by uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.tournament_players(id uuid primary key default gen_random_uuid(),tournament_id uuid references public.tournaments(id) on delete cascade,player_id uuid references public.profiles(id) on delete cascade,country_name text,country_code text,country_flag text,seed int,registered_at timestamptz default now(),status text default 'pending',unique(tournament_id,player_id));
create table public.matches(id uuid primary key default gen_random_uuid(),tournament_id uuid references public.tournaments(id) on delete cascade,round text not null,match_number int not null,player1_id uuid references public.profiles(id),player2_id uuid references public.profiles(id),player1_country text,player2_country text,score1 int,score2 int,winner_id uuid references public.profiles(id),status public.match_status default 'scheduled',scheduled_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),unique(tournament_id,round,match_number));
create table public.messages(id uuid primary key default gen_random_uuid(),sender_id uuid references public.profiles(id) on delete cascade,message text not null check(char_length(message) between 1 and 2000),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,title text not null,message text not null,type text default 'general',is_read boolean default false,created_at timestamptz default now());
create table public.announcements(id uuid primary key default gen_random_uuid(),title text not null,content text not null,image_url text,author_id uuid references public.profiles(id),published boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.staff_permissions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,permission text not null,granted_by uuid references public.profiles(id),created_at timestamptz default now(),unique(user_id,permission));
create table public.staff_invitations(id uuid primary key default gen_random_uuid(),email text not null,role public.user_role not null check(role in('president','moderator')),token text unique not null,invited_by uuid references public.profiles(id),expires_at timestamptz not null,used boolean default false,created_at timestamptz default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,target_type text,target_id uuid,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in('owner','president','moderator') and status='approved')$$;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='owner' and status='approved')$$;
alter table public.profiles enable row level security;alter table public.tournaments enable row level security;alter table public.tournament_players enable row level security;alter table public.matches enable row level security;alter table public.messages enable row level security;alter table public.notifications enable row level security;alter table public.announcements enable row level security;alter table public.staff_permissions enable row level security;alter table public.staff_invitations enable row level security;alter table public.audit_logs enable row level security;
create policy profiles_read on public.profiles for select using(status='approved' or id=auth.uid() or public.is_staff());create policy profiles_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role=(select role from profiles where id=auth.uid()) and status=(select status from profiles where id=auth.uid()));
create policy tournaments_read on public.tournaments for select using(true);create policy tournaments_staff_write on public.tournaments for all using(public.is_staff()) with check(public.is_staff());
create policy tp_read on public.tournament_players for select using(true);create policy tp_self_insert on public.tournament_players for insert with check(player_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and status='approved'));create policy tp_staff_update on public.tournament_players for update using(public.is_staff()) with check(public.is_staff());
create policy matches_read on public.matches for select using(true);create policy matches_staff_write on public.matches for all using(public.is_staff()) with check(public.is_staff());
create policy messages_read on public.messages for select using(exists(select 1 from profiles where id=auth.uid() and status='approved'));create policy messages_insert on public.messages for insert with check(sender_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and status='approved'));create policy messages_staff_delete on public.messages for delete using(public.is_staff());
create policy notifications_self_read on public.notifications for select using(user_id=auth.uid());create policy notifications_self_update on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy announcements_read on public.announcements for select using(published=true or public.is_staff());create policy announcements_staff_write on public.announcements for all using(public.is_staff()) with check(public.is_staff());
create policy permissions_owner on public.staff_permissions for all using(public.is_owner()) with check(public.is_owner());create policy invitations_owner on public.staff_invitations for all using(public.is_owner()) with check(public.is_owner());create policy audit_read on public.audit_logs for select using(public.is_staff());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,username,email,phone,efootball_id) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'username','user_'||substr(new.id::text,1,8)),new.email,new.raw_user_meta_data->>'phone',new.raw_user_meta_data->>'efootball_id');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter publication supabase_realtime add table public.messages;alter publication supabase_realtime add table public.notifications;
